def transform(x):
 if isinstance(x,str):
  if x in replacements:return replacements[x]
  for old,new in replacements.items():x=x.replace(old,new)
  return x
 if isinstance(x,list):return [transform(v) for v in x]
 if isinstance(x,dict):return {k:transform(v) for k,v in x.items()}
 return x
